      n->z_("alpha", alpha); // TODO: Intern all of these symbols?
      tracer->appendNode(n);
    }
    // ---- END ----
    auto flags = Function::flags({ self, other });
    auto grad_fn = std::make_shared<AddBackward1>();
    if (flags.is_executable) {
      grad_fn->alpha = alpha;
    } 
    auto output = as_variable(baseType->s_add(self_, other_, alpha));
    wrap_output(*output.get(), std::move(flags), std::move(grad_fn));
    // ---- BEGIN ----
